package com.aditya.fefo.service;
import com.aditya.fefo.dto.BenchmarkDtos.*; import com.aditya.fefo.domain.Batch; import com.aditya.fefo.repository.BatchRepository; import org.springframework.stereotype.Service; import java.time.LocalDate; import java.util.*;
@Service public class BenchmarkService {private final BatchRepository batches;public BenchmarkService(BatchRepository b){batches=b;} public Response run(Request r){List<Batch> data=batches.findByProductIdOrderByExpiryDateAsc(r.productId());LocalDate today=LocalDate.now();List<BatchSnapshot> base=data.stream().filter(b->!b.isExpired()&&b.getExpiryDate().isAfter(today)).map(b->new BatchSnapshot(b.getId(),b.getExpiryDate(),b.getAvailableQuantity())).toList();long nearTotal=base.stream().filter(b->!b.expiry.isAfter(today.plusDays(30))).mapToLong(b->b.qty).sum();long fefo=simulate(base,r.runs(),r.reservationQuantity(),true,today);long lifo=simulate(base,r.runs(),r.reservationQuantity(),false,today);return new Response(stat("FEFO",fefo,nearTotal),stat("LIFO",lifo,nearTotal));} private Strategy stat(String n,long left,long total){return new Strategy(n,left,total,total==0?0:Math.round(left*10000.0/total)/100);} private long simulate(List<BatchSnapshot> base,int runs,long request,boolean fefo,LocalDate today){long nearLeft=0;for(int run=0;run<runs;run++){long remainingRequest=request;long[] q=base.stream().mapToLong(x->x.qty).toArray();List<Integer> idx=new ArrayList<>();for(int i=0;i<q.length;i++)idx.add(i);if(!fefo)Collections.reverse(idx);for(int k:idx){long take=Math.min(q[k],remainingRequest);q[k]-=take;remainingRequest-=take;if(remainingRequest==0)break;}if(remainingRequest>0) {remainingRequest=0;} for(int i=0;i<q.length;i++)if(!base.get(i).expiry.isAfter(today.plusDays(30)))nearLeft+=q[i];}return runs==0?0:nearLeft/runs;} record BatchSnapshot(UUID id,LocalDate expiry,long qty){}
}
